INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(117969, 'ruRU', '', 'Твоё владение льдом позволяет призвать питомца — элементаля воды, так что начнём с этого.', 24330),
(117970, 'ruRU', '', 'Будучи магом льда, ты превосходно контролируешь поле боя, замораживая врагов на месте, пока лёд и град избивают их до покорности.', 24330),
(117971, 'ruRU', '', 'Используй Прилив сил, чтобы полностью восполнить своё здоровье.', 24330),
(117972, 'ruRU', '', 'Получение урона — часть боя, но ты можешь обратиться к духовным туманам, чтобы исцелить себя или союзника. Используй Прилив сил, чтобы вылечить свои раны.', 24330),
(117973, 'ruRU', '', 'Потренируйся использовать Перекат несколько раз.', 24330),
(117974, 'ruRU', '', 'Твоё основное средство передвижения — Перекат, что заставляет тебя быстро перекатиться на приличное расстояние в том направлении, куда ты движешься.', 24330),
(117975, 'ruRU', '', 'Ты быстр и ловок, способен молниеносно перемещаться по полю боя, как пожелаешь.', 24330),
(117976, 'ruRU', '', 'Используй Удар тигра!', 24330),
(117977, 'ruRU', '', 'Используй Удар тигра, чтобы накопить Ци!', 24330),
(117978, 'ruRU', '', 'Перекат, перекат, перекат!', 24330),
(117979, 'ruRU', '', 'Используй Удар восходящего солнца!', 24330),
(117980, 'ruRU', '', 'Удар восходящего солнца доступен! Используй его сейчас!', 24330),
(117981, 'ruRU', '', 'Используй Удар летящего змея!', 24330),
(117982, 'ruRU', '', 'Используй Кулаки ярости!', 24330),
(117983, 'ruRU', '', 'Кулаки ярости доступны! Используй их сейчас!', 24330),
(117984, 'ruRU', '', 'Исцели себя Приливом сил!', 24330),
(117985, 'ruRU', '', 'У тебя максимум Ци! Используй Удар в висок!', 24330),
(117986, 'ruRU', '', 'Используй Удар в висок!', 24330),
(117987, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как монах.', 24330),
(117988, 'ruRU', '', 'Покажи мне силу и ловкость того, кто бродит по ветру!', 24330),
(117989, 'ruRU', '', 'Обездвижь солдата, что атакует тебя, Параличом.', 24330),
(117990, 'ruRU', '', 'Выведи одного врага из боя, парализовав его! Паралич обездвижит врага на короткое время, но враг очнётся, если получит урон.', 24330),
(117991, 'ruRU', '', 'Иногда ты можешь оказаться в ситуации, когда врагов больше, чем ты способен одолеть.', 24330),
(117992, 'ruRU', '', 'Используй Удар летящего змея, чтобы переместиться к тренировочному манекену и нанести ему урон.', 24330),
(117993, 'ruRU', '', 'Используй Удар летящего змея, чтобы метнуться к врагу. Повторное использование во время полёта завершит полёт и нанесёт урон находящимся рядом врагам.', 24330),
(117994, 'ruRU', '', 'Перекат — не единственная твоя способность для передвижения. Монахи, бродящие по ветру, также могут взлетать в воздух, устремляясь к своим целям.', 24330),
(117995, 'ruRU', '', 'Используй Кулаки ярости на тренировочном манекене.', 24330),
(117996, 'ruRU', '', 'Это также поразит дополнительных врагов рядом с твоей целью. Используй Кулаки ярости, когда они доступны, или если сражаешься с несколькими врагами.', 24330),
(117997, 'ruRU', '', 'У тебя в запасе множество атак, бродящий по ветру! Кулаки ярости стоят 3 Ци и наносят большой урон.', 24330),
(117998, 'ruRU', '', 'Используй Удар в висок на тренировочном манекене.', 24330),
(117999, 'ruRU', '', 'Он бьёт намного сильнее, чем Удар тигра, так что используй Удар в висок, чтобы потратить лишнюю Ци.', 24330),
(118000, 'ruRU', '', 'Хоть и не такой мощный, как Удар восходящего солнца, твой Удар в висок всё же бьёт крепко... ну, в смысле, пинает крепко!', 24330),
(118001, 'ruRU', '', 'Используй Удар восходящего солнца на тренировочном манекене.', 24330),
(118002, 'ruRU', '', 'Используй его, когда он доступен.', 24330),
(118003, 'ruRU', '', 'Начало боя с Удара тигра даёт тебе достаточно Ци, чтобы высвободить мощный Удар восходящего солнца — атаку, что использует 2 Ци и наносит значительный урон.', 24330),
(118004, 'ruRU', '', 'Используй Удар тигра на тренировочном манекене.', 24330),
(118005, 'ruRU', '', 'Начни с использования своей основной атаки, Удара тигра, чтобы наносить урон и накапливать Ци.', 24330),
(118006, 'ruRU', '', 'Это накапливает Ци — ресурс, позволяющий высвобождать твои самые мощные атаки.', 24330),
(118007, 'ruRU', '', 'Будучи монахом, бродящим по ветру, ты используешь свои кулаки и скорость, чтобы одолевать врагов.', 24330),
(118008, 'ruRU', '', 'Используй Вспышку света, чтобы исцелить свои раны.', 24330);
